def changed_paths(before, after):
    def _recurse(b, a, prefix):
        results = set()
        all_keys = set(b.keys()) | set(a.keys())
        for key in all_keys:
            path = f"{prefix}.{key}" if prefix else key
            if key not in a:
                results.add(path)
            elif key not in b:
                results.add(path)
            else:
                bv, av = b[key], a[key]
                if isinstance(bv, dict) and isinstance(av, dict):
                    results.update(_recurse(bv, av, path))
                elif bv != av:
                    results.add(path)
        return results
    return sorted(_recurse(before, after, ""))
```

