def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    Raises ValueError if the path is not absolute (does not start with '/').
    Collapses repeated slashes, ignores '.' components, and resolves '..'
    without going above root. Returns '/' for the root directory and never
    includes a trailing slash for non-root paths.
    """
    if not path.startswith("/"):
        raise ValueError(f"Path must be absolute: {path!r}")

    parts = path.split("/")
    stack: list[str] = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
            # else: ignore, cannot go above root
        else:
            stack.append(part)

    if not stack:
        return "/"
    return "/" + "/".join(stack)
```

